insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('390dea2c-63f1-4eb8-9fa9-1f8f95e4d0f0', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', null, 'topic'::public.curated_course_node_type, 'Manufacturing Strategy, Materials, and Process Selection', 'This opening topic frames manufacturing as an engineering decision system: the right process depends on function, material behavior, tolerances, quantity, cost, and lifecycle priorities.', 0),
  ('8547b6de-c48a-415c-9046-8fa5b419dd93', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '390dea2c-63f1-4eb8-9fa9-1f8f95e4d0f0', 'subtopic'::public.curated_course_node_type, 'Manufacturing process families', 'Why it matters: Students learn the map of manufacturing so later details fit into a usable decision framework.', 0),
  ('e7062cdc-0da4-4e19-a7fb-21bf35852c1e', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '8547b6de-c48a-415c-9046-8fa5b419dd93', 'concept'::public.curated_course_node_type, 'Primary shaping, forming, subtractive, joining, surface processing, additive, and assembly', null, 0),
  ('99711f95-b33c-4fb7-8ca4-49452969f2e3', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '8547b6de-c48a-415c-9046-8fa5b419dd93', 'concept'::public.curated_course_node_type, 'Process capability windows: geometry, material, tolerance, throughput, and cost', null, 1),
  ('e2a23cc0-eb5a-4441-9fe9-7f54153ae805', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '8547b6de-c48a-415c-9046-8fa5b419dd93', 'concept'::public.curated_course_node_type, 'Product lifecycle stages from prototype to production ramp', null, 2),
