  ('6b3bd29f-0194-47f7-99aa-057ebebed7be', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '4c091a1f-68c4-4707-8004-c3c2493fd220', 'concept'::public.curated_course_node_type, 'Metals, polymers, ceramics, composites, and powders', null, 0),
  ('e1981037-f284-4933-a9f2-003edde39c32', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '4c091a1f-68c4-4707-8004-c3c2493fd220', 'concept'::public.curated_course_node_type, 'Strength, ductility, hardness, melting behavior, thermal properties, and machinability', null, 1),
  ('ab096d6b-7c9c-4535-8a0d-e22c8e55348c', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '4c091a1f-68c4-4707-8004-c3c2493fd220', 'concept'::public.curated_course_node_type, 'Processing-structure-property relationships', null, 2),
  ('0dbb9c47-5b30-4e4c-976f-c0cc15592637', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '390dea2c-63f1-4eb8-9fa9-1f8f95e4d0f0', 'subtopic'::public.curated_course_node_type, 'Process selection logic', 'Why it matters: Students practice choosing processes by balancing constraints rather than memorizing isolated methods.', 2),
  ('1ae8fad3-091f-430d-9df8-db68d8f21243', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '0dbb9c47-5b30-4e4c-976f-c0cc15592637', 'concept'::public.curated_course_node_type, 'Part function, material compatibility, geometry, tolerance, surface finish, and production volume', null, 0),
  ('486163e9-626c-4127-b669-1cee8c249cde', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '0dbb9c47-5b30-4e4c-976f-c0cc15592637', 'concept'::public.curated_course_node_type, 'Make-buy decisions, supplier capability, and equipment availability', null, 1),
  ('eadd426b-817a-4c77-ac91-53e260bbca86', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '0dbb9c47-5b30-4e4c-976f-c0cc15592637', 'concept'::public.curated_course_node_type, 'Tradeoffs among performance, cost, speed, quality, and sustainability', null, 2),
  ('0684691e-e0fd-49dc-8a90-ed49daa5b9ed', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', null, 'topic'::public.curated_course_node_type, 'Casting, Molding, and Primary Shaping Processes', 'Casting and molding introduce how liquid or softened material becomes a finished or near-net-shape part, making this topic central for metals, polymers, and high-volume production.', 1),
  ('bd484c9f-bb15-4789-836a-92c3dce0a178', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '0684691e-e0fd-49dc-8a90-ed49daa5b9ed', 'subtopic'::public.curated_course_node_type, 'Foundry fundamentals', 'Why it matters: Students see how molten metal handling, solidification, and tooling shape final quality.', 0),
  ('7161544a-2924-44ac-8994-1d6bdb65b901', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'bd484c9f-bb15-4789-836a-92c3dce0a178', 'concept'::public.curated_course_node_type, 'Patterns, molds, cores, gating, risers, shrinkage, and feeding', null, 0),
  ('1d94cc68-8037-46bb-921c-f98aa3a7a6ac', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'bd484c9f-bb15-4789-836a-92c3dce0a178', 'concept'::public.curated_course_node_type, 'Sand casting, investment casting, die casting, and permanent mold casting', null, 1),
  ('80d0a0c5-9ba7-415b-8e88-52ea84e56c6b', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'bd484c9f-bb15-4789-836a-92c3dce0a178', 'concept'::public.curated_course_node_type, 'Solidification defects, porosity, inclusions, and hot tears', null, 2),
  ('6146f585-e6c2-4f5b-ba4a-287d78dd8838', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '0684691e-e0fd-49dc-8a90-ed49daa5b9ed', 'subtopic'::public.curated_course_node_type, 'Polymer molding foundations', 'Why it matters: The point is to understand why plastic part design depends so strongly on tooling and flow.', 1),
  ('9946f4ae-b16b-456c-bfd1-3c843a5e2457', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '6146f585-e6c2-4f5b-ba4a-287d78dd8838', 'concept'::public.curated_course_node_type, 'Injection molding, compression molding, blow molding, thermoforming, and extrusion molding', null, 0),
  ('a14d075f-20bc-4075-8e8e-c122040b976b', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '6146f585-e6c2-4f5b-ba4a-287d78dd8838', 'concept'::public.curated_course_node_type, 'Flow length, cooling, shrinkage, warpage, draft, ribs, bosses, and sink marks', null, 1),
  ('67e8ca3e-b005-43f1-83e3-05b5c870fbfb', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '6146f585-e6c2-4f5b-ba4a-287d78dd8838', 'concept'::public.curated_course_node_type, 'Thermoplastics versus thermosets', null, 2),
  ('7e0eeb2c-0a77-4f12-92d0-28d56b7f8b37', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '0684691e-e0fd-49dc-8a90-ed49daa5b9ed', 'subtopic'::public.curated_course_node_type, 'Casting and molding design rules', 'Why it matters: Students learn to design parts that a real shop can produce consistently.', 2),
  ('dc90f1a0-79db-425f-814c-d03d59b5e084', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '7e0eeb2c-0a77-4f12-92d0-28d56b7f8b37', 'concept'::public.curated_course_node_type, 'Parting lines, draft angles, wall thickness, corner radii, and ejection', null, 0),
  ('64e3040d-ebff-412b-bf0c-a4b4d2d0765e', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '7e0eeb2c-0a77-4f12-92d0-28d56b7f8b37', 'concept'::public.curated_course_node_type, 'Tooling cost and volume economics', null, 1),
  ('ecfe4c2c-917f-4c7f-b86f-d074a83071b7', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '7e0eeb2c-0a77-4f12-92d0-28d56b7f8b37', 'concept'::public.curated_course_node_type, 'Inspection needs for internal and surface defects', null, 2),
  ('a6d18487-38a4-4ce9-96b0-8a89ecdb6d76', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', null, 'topic'::public.curated_course_node_type, 'Bulk Deformation: Forging, Rolling, Extrusion, and Drawing', 'Bulk deformation processes reshape material through plastic flow, so the emphasis is on force, temperature, tooling, grain flow, and property changes.', 2),
  ('b6fb7ff7-0d99-4248-a0e9-af3ec35cc430', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'a6d18487-38a4-4ce9-96b0-8a89ecdb6d76', 'subtopic'::public.curated_course_node_type, 'Deformation mechanics', 'Why it matters: Students learn why plastic deformation can improve strength but also create defects if poorly controlled.', 0),
  ('4b4eeed7-585d-4ee3-858d-98eb09f739a9', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'b6fb7ff7-0d99-4248-a0e9-af3ec35cc430', 'concept'::public.curated_course_node_type, 'Stress-strain behavior beyond yield', null, 0),
  ('2701ca03-d493-424f-af3c-37a2e8cd029d', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'b6fb7ff7-0d99-4248-a0e9-af3ec35cc430', 'concept'::public.curated_course_node_type, 'Cold, warm, and hot working', null, 1),
  ('473893f3-77ac-4279-b106-b2575e48ff56', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'b6fb7ff7-0d99-4248-a0e9-af3ec35cc430', 'concept'::public.curated_course_node_type, 'Work hardening, recrystallization, anisotropy, and grain flow', null, 2),
  ('047e628f-8e80-423d-8623-748ec2c2be61', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'a6d18487-38a4-4ce9-96b0-8a89ecdb6d76', 'subtopic'::public.curated_course_node_type, 'Major bulk forming processes', 'Why it matters: The goal is to distinguish process capabilities and when each process is economically appropriate.', 1),
  ('e546294a-1843-4b66-98c6-dc8a2f264393', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '047e628f-8e80-423d-8623-748ec2c2be61', 'concept'::public.curated_course_node_type, 'Forging, rolling, extrusion, wire drawing, bar drawing, and swaging', null, 0),
  ('38f95a8c-954e-43ba-aec4-108691d6a9e9', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '047e628f-8e80-423d-8623-748ec2c2be61', 'concept'::public.curated_course_node_type, 'Open-die versus closed-die tooling', null, 1),
  ('41f94bf9-3dfa-482e-afb3-9e4ee11b061b', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '047e628f-8e80-423d-8623-748ec2c2be61', 'concept'::public.curated_course_node_type, 'Load, friction, lubrication, temperature, and die wear', null, 2),
  ('f15641d8-b11a-4759-8309-42ccac4167da', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'a6d18487-38a4-4ce9-96b0-8a89ecdb6d76', 'subtopic'::public.curated_course_node_type, 'Forming defects and quality', 'Why it matters: Students learn the failure modes that limit manufacturability.', 2),
  ('450e2f00-177b-4691-ab11-98500e1bd76f', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'f15641d8-b11a-4759-8309-42ccac4167da', 'concept'::public.curated_course_node_type, 'Cracks, laps, seams, residual stresses, center burst, and dimensional variation', null, 0),
  ('c676354b-3aca-4454-9a4d-bd2db48f51cd', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'f15641d8-b11a-4759-8309-42ccac4167da', 'concept'::public.curated_course_node_type, 'Process maps, forming limits, and lubrication control', null, 1),
  ('fa727f15-99ad-447a-8d6b-1d5aaea59322', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'f15641d8-b11a-4759-8309-42ccac4167da', 'concept'::public.curated_course_node_type, 'Inspection and post-forming heat treatment', null, 2),
  ('4e56d365-a73f-4ed5-89e7-05c7d6f0bc10', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', null, 'topic'::public.curated_course_node_type, 'Sheet Metal Forming and Pressworking', 'Sheet forming covers the processes used for enclosures, vehicle bodies, appliances, brackets, and stamped components where thin material must hold precise shape.', 3),
  ('08302bb0-1107-455d-baee-14903da3cc11', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '4e56d365-a73f-4ed5-89e7-05c7d6f0bc10', 'subtopic'::public.curated_course_node_type, 'Sheet forming operations', 'Why it matters: Students learn the standard operations behind high-volume metal parts.', 0),
  ('5deef2a9-ef2e-4c72-a8a3-9d13f5069544', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '08302bb0-1107-455d-baee-14903da3cc11', 'concept'::public.curated_course_node_type, 'Shearing, blanking, punching, bending, deep drawing, stretching, and roll forming', null, 0),
  ('2f9fb381-871b-41d4-9338-f750cafbe69f', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '08302bb0-1107-455d-baee-14903da3cc11', 'concept'::public.curated_course_node_type, 'Presses, dies, punches, blank holders, and progressive tooling', null, 1),
  ('3da3ee97-093a-45ec-82c8-18b859f96470', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '08302bb0-1107-455d-baee-14903da3cc11', 'concept'::public.curated_course_node_type, 'Springback, bend allowance, bend radius, and neutral axis', null, 2),
  ('a5543815-060c-41dd-9991-bdbd6794fd10', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '4e56d365-a73f-4ed5-89e7-05c7d6f0bc10', 'subtopic'::public.curated_course_node_type, 'Formability and failure', 'Why it matters: The point is to predict when sheet material can stretch or draw without tearing or wrinkling.', 1),
  ('ea8d663a-5800-4959-841b-c30f3f62edb9', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'a5543815-060c-41dd-9991-bdbd6794fd10', 'concept'::public.curated_course_node_type, 'Forming-limit diagrams', null, 0),
  ('69d29e50-9321-472f-9313-7b3abe8ade71', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'a5543815-060c-41dd-9991-bdbd6794fd10', 'concept'::public.curated_course_node_type, 'Wrinkling, tearing, earing, thinning, and residual stress', null, 1),
  ('41b21326-9f0c-455c-9983-e114f94dea1c', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'a5543815-060c-41dd-9991-bdbd6794fd10', 'concept'::public.curated_course_node_type, 'Material anisotropy and lubrication', null, 2),
  ('be44f57e-3c3d-4d37-abf3-53b98c75dc1f', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '4e56d365-a73f-4ed5-89e7-05c7d6f0bc10', 'subtopic'::public.curated_course_node_type, 'Design for stamped parts', 'Why it matters: Students connect part design choices to tooling complexity and production yield.', 2),
  ('863c619e-da1c-4087-a8d1-6a951597e589', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'be44f57e-3c3d-4d37-abf3-53b98c75dc1f', 'concept'::public.curated_course_node_type, 'Hole-to-edge spacing, bend relief, corner radii, and consistent wall features', null, 0),
  ('fc1b816f-df85-4327-b065-c3763d9dba46', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'be44f57e-3c3d-4d37-abf3-53b98c75dc1f', 'concept'::public.curated_course_node_type, 'Tooling cost, nesting, scrap, and production volume', null, 1),
  ('dc09de2b-7d1a-4aa2-8888-43e8ace9de47', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'be44f57e-3c3d-4d37-abf3-53b98c75dc1f', 'concept'::public.curated_course_node_type, 'Tolerance stack-up and secondary operations', null, 2),
  ('b8953194-4abf-411f-bcfb-7ab8d0636ab9', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', null, 'topic'::public.curated_course_node_type, 'Machining Fundamentals and Cutting Processes', 'Machining is the core subtractive process family; students learn how tools remove material while controlling accuracy, surface finish, tool life, and cost.', 4),
  ('922c7eb3-01fc-4c55-a56d-b526a9ee0a1c', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'b8953194-4abf-411f-bcfb-7ab8d0636ab9', 'subtopic'::public.curated_course_node_type, 'Cutting mechanics', 'Why it matters: This subtopic explains what happens at the tool-chip interface and why cutting conditions matter.', 0),
  ('61b62364-461c-498e-8376-a30e1099d50e', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '922c7eb3-01fc-4c55-a56d-b526a9ee0a1c', 'concept'::public.curated_course_node_type, 'Chip formation, shear plane, built-up edge, cutting forces, and power', null, 0),
  ('1d4b653e-a9a6-4de7-82c9-4d94e7c065db', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '922c7eb3-01fc-4c55-a56d-b526a9ee0a1c', 'concept'::public.curated_course_node_type, 'Tool materials, coatings, rake angle, clearance angle, and wear', null, 1),
  ('13c68b8e-cd9a-4a36-a66c-c01338083527', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '922c7eb3-01fc-4c55-a56d-b526a9ee0a1c', 'concept'::public.curated_course_node_type, 'Speed, feed, depth of cut, material removal rate, and tool life', null, 2),
  ('54e4268c-99de-45d9-b9b5-edce2bd8d6dc', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'b8953194-4abf-411f-bcfb-7ab8d0636ab9', 'subtopic'::public.curated_course_node_type, 'Common machining operations', 'Why it matters: Students learn what each machine tool does and which geometries it produces well.', 1),
  ('bb8ccbf0-3e8e-452c-801e-4be5dbc56932', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '54e4268c-99de-45d9-b9b5-edce2bd8d6dc', 'concept'::public.curated_course_node_type, 'Turning, facing, boring, drilling, reaming, tapping, milling, broaching, sawing, and shaping', null, 0),
  ('3ccfbadd-be28-45a0-b427-2ffec12b4d2e', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '54e4268c-99de-45d9-b9b5-edce2bd8d6dc', 'concept'::public.curated_course_node_type, 'Workholding, fixturing, datums, and setup planning', null, 1),
  ('435b796a-a256-4c96-8c6c-a081ea7ccb48', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '54e4268c-99de-45d9-b9b5-edce2bd8d6dc', 'concept'::public.curated_course_node_type, 'Manual versus CNC machine tools', null, 2),
  ('b1b88f7c-1ba7-4943-9f3f-08af42a36f04', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'b8953194-4abf-411f-bcfb-7ab8d0636ab9', 'subtopic'::public.curated_course_node_type, 'Machining economics and quality', 'Why it matters: The goal is to make process plans that meet tolerance without wasting time or tooling.', 2),
  ('4c7f0d02-04ad-4802-acbd-d50e1145b076', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'b1b88f7c-1ba7-4943-9f3f-08af42a36f04', 'concept'::public.curated_course_node_type, 'Cycle time, setup time, tool change time, and batch size', null, 0),
  ('37d26eaa-06e8-4dab-9a9f-195cdafde15f', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'b1b88f7c-1ba7-4943-9f3f-08af42a36f04', 'concept'::public.curated_course_node_type, 'Surface finish, dimensional accuracy, burrs, chatter, and heat effects', null, 1),
  ('5f9aeaa4-cfc5-417e-8f6f-12087febd04e', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'b1b88f7c-1ba7-4943-9f3f-08af42a36f04', 'concept'::public.curated_course_node_type, 'Roughing and finishing strategy', null, 2),
  ('ac113c9c-15af-4b38-bcac-86f7e45dcf5a', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', null, 'topic'::public.curated_course_node_type, 'Abrasive Machining, Finishing, and Surface Treatments', 'Finishing processes determine final accuracy, surface integrity, wear behavior, and appearance, especially when conventional machining cannot deliver required tolerances.', 5),
