  ('ba5b8ccc-ee2c-4f11-9c29-777946b1bffe', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '6b2ab343-4274-4a50-9acb-ed21a7820a10', 'concept'::public.curated_course_node_type, 'Grinding, honing, lapping, polishing, abrasive blasting, and superfinishing', null, 0),
