  ('fdbce0dc-bd30-4f94-b843-0ceb11053019', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'dfa925d7-c4a8-44f6-a9a4-419a423ca736', 'concept'::public.curated_course_node_type, 'Arc welding, resistance welding, laser welding, brazing, soldering, friction welding, and ultrasonic welding', null, 0),
