  ('be069816-6188-4ab4-bb4d-071f9d547b40', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'dfa925d7-c4a8-44f6-a9a4-419a423ca736', 'concept'::public.curated_course_node_type, 'Weld symbols, joint preparation, filler metals, shielding, and process variables', null, 2),
