  ('5547d3f4-1776-4409-a57a-40dc4d5f5276', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '31270e7a-e747-4813-a03d-1f874a9abd3d', 'concept'::public.curated_course_node_type, 'Material extrusion, vat photopolymerization, powder bed fusion, binder jetting, directed energy deposition, sheet lamination, and material jetting', null, 0),
