  ('7d8aa565-7029-4147-8f86-fd25d48153a2', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '31270e7a-e747-4813-a03d-1f874a9abd3d', 'concept'::public.curated_course_node_type, 'Build orientation, supports, layer thickness, infill, and post-processing', null, 2),
