  ('da305f7a-8982-4a41-b920-1584d7ef3377', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'f06de1eb-e169-4c27-9b02-83e1a5c4306c', 'concept'::public.curated_course_node_type, 'Topology optimization, lattice structures, consolidation, internal channels, and mass customization', null, 0),
