  ('78f7c60e-8817-4a77-a8c2-6a9a296a79ce', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'a756a403-fcbb-45b8-9492-2efea5bbabef', 'concept'::public.curated_course_node_type, 'Process monitoring, material traceability, build records, and inspection', null, 0),
  ('420d1fd9-16de-4ff3-baeb-d58f69f5e6db', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'a756a403-fcbb-45b8-9492-2efea5bbabef', 'concept'::public.curated_course_node_type, 'Cost models for prototype, bridge, and production quantities', null, 1),
