  ('650b60c9-5fe8-4c47-9319-947bc8b992ac', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '054c836a-d877-447b-aee0-56c388a2da1b', 'concept'::public.curated_course_node_type, 'CAD models, setup sheets, tool libraries, toolpaths, post-processors, and G-code', null, 0),
