  ('bfe1ac93-de3d-4be1-8bcf-d8a1573bde71', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '054c836a-d877-447b-aee0-56c388a2da1b', 'concept'::public.curated_course_node_type, 'Collision checking, verification, and first-article approval', null, 2),
