  ('da2d01fb-6407-4d95-91b0-9627d0b97ae7', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '1950b1e9-270e-4e9f-9628-c91d26deccae', 'concept'::public.curated_course_node_type, 'Digital twins, MES, SCADA, IIoT, machine connectivity, and data standards', null, 0),
  ('dd057512-9e01-4ed4-8ff4-b2bcf0fd0fc2', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '1950b1e9-270e-4e9f-9628-c91d26deccae', 'concept'::public.curated_course_node_type, 'OEE, downtime tracking, process dashboards, and alarms', null, 1),
