  ('2f283141-3922-483c-b3e3-2316b90eb285', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', null, 'topic'::public.curated_course_node_type, 'Process Planning, Routing, Tooling, and Production Ramp', 'Process planning turns a design into an executable manufacturing route, so students practice sequencing operations, selecting tooling, estimating capacity, and preparing for scale-up.', 10),
