  ('6bc988c9-fde7-4b07-a783-0052dc78ff25', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '107fff87-86af-4925-b271-92fb6473bbc2', 'concept'::public.curated_course_node_type, 'Operation sequence, setup strategy, datum transfer, work instructions, and inspection hold points', null, 0),
  ('7767ef5d-be45-4ab0-b804-b18a911a689b', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '107fff87-86af-4925-b271-92fb6473bbc2', 'concept'::public.curated_course_node_type, 'Machine selection, fixture selection, tool selection, and outsourcing decisions', null, 1),
  ('d2a2f6ef-8564-41f4-877b-31d9bae1d4ec', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '107fff87-86af-4925-b271-92fb6473bbc2', 'concept'::public.curated_course_node_type, 'Process sheets, travelers, bills of materials, and revision control', null, 2),
  ('bfbff136-69d8-4a99-ad68-63cb5b61e347', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '2f283141-3922-483c-b3e3-2316b90eb285', 'subtopic'::public.curated_course_node_type, 'Tooling and fixtures', 'Why it matters: The goal is to see tooling as a major driver of accuracy, speed, repeatability, and cost.', 1),
  ('d3c651de-9ff7-43cd-8fd4-affb4bc75252', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'bfbff136-69d8-4a99-ad68-63cb5b61e347', 'concept'::public.curated_course_node_type, 'Jigs, fixtures, dies, molds, cutting tools, gauges, and custom workholding', null, 0),
  ('66361742-7cf5-432e-b51a-c2d10f49ab10', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'bfbff136-69d8-4a99-ad68-63cb5b61e347', 'concept'::public.curated_course_node_type, 'Tool life, maintainability, spare tooling, and setup reduction', null, 1),
  ('d12b6501-a01b-4a0d-8277-4d15c89f41e5', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', 'bfbff136-69d8-4a99-ad68-63cb5b61e347', 'concept'::public.curated_course_node_type, 'Capital cost versus per-part cost', null, 2),
  ('73b477f5-a551-404b-b594-c357e4d65753', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '2f283141-3922-483c-b3e3-2316b90eb285', 'subtopic'::public.curated_course_node_type, 'Prototype to production ramp', 'Why it matters: Students learn why processes that work once must be stabilized before scale.', 2),
  ('1465315e-b990-4b5c-bb24-ed79c0d3df00', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '73b477f5-a551-404b-b594-c357e4d65753', 'concept'::public.curated_course_node_type, 'Pilot builds, first articles, capability studies, and production readiness reviews', null, 0),
  ('8d969a2b-24ed-470b-a55a-fb91b34b1ae1', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '73b477f5-a551-404b-b594-c357e4d65753', 'concept'::public.curated_course_node_type, 'Supplier qualification, documentation, training, and control plans', null, 1),
