  ('89ff889e-3eea-4468-b910-76a5b520487e', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '9b1ecd87-ffe7-438b-a2fe-76e133390580', 'concept'::public.curated_course_node_type, 'Calipers, micrometers, height gauges, CMMs, optical comparators, gauges, and scanners', null, 0),
