  ('d88636ec-69ab-42a9-af58-043df3e76748', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '9b1ecd87-ffe7-438b-a2fe-76e133390580', 'concept'::public.curated_course_node_type, 'Gauge R&R and measurement system analysis', null, 2),
