  ('d6577b45-0814-477e-8620-f3f22c241df1', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '395caa0a-46b0-42db-be54-4c9527280659', 'concept'::public.curated_course_node_type, 'Datums, basic dimensions, position, flatness, parallelism, perpendicularity, runout, and profile', null, 0),
