  ('41e272da-4809-45a6-90d9-193df88ff494', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '02c7abd6-07fe-487e-b073-ae53bd7fb556', 'concept'::public.curated_course_node_type, 'Control charts, process capability indices Cp and Cpk, sampling plans, and acceptance criteria', null, 0),
  ('e715a55d-900a-43bf-8adf-548965b7d17a', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '02c7abd6-07fe-487e-b073-ae53bd7fb556', 'concept'::public.curated_course_node_type, 'Pareto charts, root cause analysis, corrective action, and continuous improvement', null, 1),
