  ('b44d86bc-d6d3-475b-b110-d2d1ccf39ece', 'cd6d5f52-d469-44b3-ac2d-6eb0bc27efd9', '37afee3d-8a8c-4316-999d-077a231ee40e', 'concept'::public.curated_course_node_type, 'Energy use, material yield, emissions, coolant, waste, and hazardous substances', null, 0),
